about_disclaimer_piracy: "ใช้กับฮาร์ดแวร์ที่คุณเป็นเจ้าของและเนื้อหาที่คุณครอบครองโดยชอบด้วยกฎหมายเท่านั้น ห้ามใช้เพื่อคัดลอก เผยแพร่ หรือเรียกใช้ซอฟต์แวร์ที่คุณไม่มีสิทธิ์ใช้งาน",
about_disclaimer_risk: "ซอฟต์แวร์นี้จัดหาให้ “ตามสภาพ” โดยไม่มีการรับประกันใด ๆ ทั้งสิ้น การใช้งานเครื่องที่ถูกดัดแปลงอาจทำให้เครื่องเสียหายอย่างถาวร ทำลายเซฟและสิทธิ์การใช้งานอย่างไม่อาจกู้คืนได้ และอาจทำให้บัญชีหรือเครื่องของคุณถูกแบน คุณใช้งานโดยยอมรับความเสี่ยงเองทั้งหมดและรับผิดชอบผลที่ตามมาอย่างเต็มที่ กรุณาสำรองข้อมูลทุกอย่างที่คุณไม่อาจสูญเสียได้ก่อนเริ่มต้น",
