"fpkg.aboutSource": "แหล่งต้องเป็นโครงสร้างเกมที่ถอดรหัสแล้ว การติดตั้งแบบรีเทลแตกออกที่นี่ไม่ได้ และการตรวจสอบด้านล่างจะแจ้งหากคุณเลือกแบบนั้น",
"fpkg.aboutFake": "ผลลัพธ์เป็นแพ็กเกจปลอม คอนโซลจึงต้องโหลดการรองรับแพ็กเกจปลอมก่อนติดตั้ง: kstuff (รุ่นที่รองรับแพ็กเกจปลอมของ PS5), a53_ppr_install_fast.elf และ shadowmountplus.elf ตามลำดับนี้ หน้าติดตั้งแพ็กเกจก็บอกเช่นเดียวกันข้างปุ่มติดตั้ง",
"fpkg.aboutChecks": "สิ่งที่การตรวจสอบมองหา",
"fpkg.checkEboot": "eboot.bin ที่รากของโครงสร้าง — โมดูลเกม ต้องเป็น ELF ดิบหรือ SELF ที่ห่อไว้ โมดูลที่ลงนามแบบรีเทลแพ็กใหม่ไม่ได้",
"fpkg.checkParam": "มี sce_sys/param.json และไม่มี sce_sys/param.sfo — param.sfo จะทำให้คอนโซลเปิดเกมตามเส้นทางของ PS4",
"fpkg.checkIcons": "รหัสเนื้อหา 36 ตัวอักษร ไอคอนทั้งสอง และโมดูลสิทธิ์ sce_sys/about/right.sprx",
"fpkg.checkDrm": "ค่า DRM ของแพ็กเกจเป็นค่ามาตรฐาน ค่าแบบฟรีหรืออัปเกรดได้จะทำให้คอนโซลล็อกเกม ค่าจะถูกเขียนใหม่เฉพาะในแพ็กเกจ ไฟล์ของคุณเองจะไม่ถูกแตะต้อง",
"payloads_essentials_title": "แนะนำให้ใช้คู่กับ ps5upload",
"payloads_essentials_body": "หากคุณตั้งค่าคอนโซลเป็นครั้งแรก สามตัวนี้ครอบคลุมสิ่งที่ ps5upload ต้องการเกือบทั้งหมด: kstuff-lite (แพตช์เคอร์เนลที่โฮมบรูส่วนใหญ่พึ่งพา), ShadowMount+ (เมานต์อิมเมจเกมจากที่จัดเก็บ) และ nanoDNS (กันคอนโซลออกจากเส้นทางอัปเดตของ Sony) ที่เหลือในรายการนี้เป็นตัวเลือกเสริม",
