"joberr.ava1_wrong_console": "อุปกรณ์ที่ที่อยู่นี้ไม่ใช่ PS5 ที่จับคู่กับแอปนี้ ตรวจสอบที่อยู่ หรือจับคู่กับคอนโซลนี้ใหม่",
