"joberr.ava1_7z_corrupt": "อ่านไฟล์ .7z นี้ไม่ได้: ไฟล์เสียหายหรือไม่สมบูรณ์ ดาวน์โหลดหรือสร้างใหม่ แล้วลองอีกครั้ง",
